const $=id=>document.getElementById(id);
const inventory=$('cars-grid'),authDialog=$('auth-dialog'),listingDialog=$('listing-dialog'),recoveryDialog=$('recovery-dialog'),resetDialog=$('reset-dialog');
const photoField=document.querySelector('#listing-form input[name="image"]');photoField.type='file';photoField.accept='image/jpeg,image/png,image/webp';photoField.closest('label').firstChild.textContent='Fotos do veículo';photoField.parentElement.querySelector('small').textContent='JPG, PNG ou WebP · até 4 MB';
let seller=null,authMode='register',cars=[],myListings=[],storefrontStore=null;const pageParams=new URLSearchParams(location.search),legacyStorefrontId=pageParams.get('vendedor'),storeSlugParam=(pageParams.get('loja')||'').toLowerCase(),resetToken=new URLSearchParams(location.hash.slice(1)).get('token');
const storefrontSellerId=()=>storefrontStore?.id||legacyStorefrontId;
const seenListings=new Set();
function trackMetric(listingId,event){try{fetch('/api/metrics',{method:'POST',credentials:'same-origin',keepalive:true,headers:{'content-type':'application/json'},body:JSON.stringify({listingId,event})}).catch(()=>{});}catch{}}
const viewObserver=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;viewObserver.unobserve(entry.target);const id=entry.target.dataset.listingId;if(!id||seenListings.has(id))continue;seenListings.add(id);trackMetric(id,'view');}},{threshold:0.5}):null;
inventory.addEventListener('click',event=>{const link=event.target.closest('.interest-link');const id=link?.closest('[data-listing-id]')?.dataset.listingId;if(id)trackMetric(id,'whatsapp');});
const currency=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const number=new Intl.NumberFormat('pt-BR');
const brandField=$('car-brand-select'),modelField=$('car-model-select');let vehicleBrands=[];const modelCache=new Map();
async function loadVehicleBrands(){brandField.innerHTML='<option value="">Carregando marcas…</option>';try{const response=await fetch('https://brasilapi.com.br/api/fipe/marcas/v1/carros');if(!response.ok)throw new Error('Catálogo indisponível');vehicleBrands=await response.json();if(!Array.isArray(vehicleBrands)||!vehicleBrands.length)throw new Error('Catálogo inválido');vehicleBrands.sort((a,b)=>a.nome.localeCompare(b.nome,'pt-BR'));brandField.innerHTML='<option value="">Selecione uma marca</option>'+vehicleBrands.map(item=>`<option value="${escapeAttr(item.nome)}" data-code="${escapeAttr(item.valor)}">${escapeHTML(item.nome)}</option>`).join('');$('brand-help').textContent=`${vehicleBrands.length} marcas disponíveis no catálogo.`;}catch{brandField.innerHTML='<option value="">Catálogo indisponível</option>';brandField.disabled=true;$('brand-help').textContent='Não foi possível carregar o catálogo. Tente novamente mais tarde.';}}
brandField.addEventListener('change',async()=>{const code=brandField.selectedOptions[0]?.dataset.code;modelField.disabled=true;modelField.innerHTML='<option value="">Carregando modelos…</option>';if(!code){modelField.innerHTML='<option value="">Escolha primeiro a marca</option>';return;}let models=modelCache.get(code);if(!models){try{const response=await fetch(`https://brasilapi.com.br/api/fipe/veiculos/v1/carros/${encodeURIComponent(code)}`);if(!response.ok)throw new Error('Modelos indisponíveis');models=await response.json();if(!Array.isArray(models)||!models.length)throw new Error('Modelos inválidos');modelCache.set(code,models);}catch{modelField.innerHTML='<option value="">Modelos indisponíveis</option>';modelField.disabled=true;$('model-help').textContent='Não foi possível carregar os modelos desta marca.';return;}}modelField.innerHTML='<option value="">Selecione um modelo</option>'+models.map(item=>`<option value="${escapeAttr(item.modelo)}">${escapeHTML(item.modelo)}</option>`).join('');modelField.disabled=false;$('model-help').textContent=`${models.length} modelos disponíveis. Selecione o correspondente ao veículo.`;});
loadVehicleBrands();
function message(id,text,error=false){const node=$(id);node.textContent=text;node.classList.toggle('error',error);}
function cardHTML(car,own=false){const photo=car.image?`<img loading="lazy" src="/media/${encodeURIComponent(car.image)}" alt="${escapeHTML(car.make+' '+car.model)}" onerror="this.hidden=true;this.parentElement.classList.add('no-photo')">`:'';const metrics=own?`<p class="card-metrics" title="Visitas de compradores ao anúncio e cliques no botão de WhatsApp"><span>${number.format(car.views||0)} ${car.views===1?'visualização':'visualizações'}</span><i>·</i><span>${number.format(car.whatsappClicks||0)} ${car.whatsappClicks===1?'contato pelo WhatsApp':'contatos pelo WhatsApp'}</span></p>`:'';return `<article class="car-card" data-listing-id="${escapeAttr(car.id)}"><div class="car-photo ${car.image?'':'no-photo'}">${photo}<span class="car-condition">${car.year} · ${number.format(car.mileage)} km</span></div><div class="car-card-copy"><span class="car-loc">${escapeHTML(car.location||'Brasil')} <i>·</i> ${escapeHTML(car.sellerName||'')}</span><h3>${escapeHTML(car.make)} <span>${escapeHTML(car.model)}</span></h3><p class="car-description">${escapeHTML(car.description||'Consulte mais detalhes com o vendedor.')}</p>${metrics}<div class="car-offer"><strong>${currency.format(car.price/100)}</strong><a class="interest-link" target="_blank" rel="noopener noreferrer" href="https://wa.me/${escapeAttr(car.whatsapp)}?text=${encodeURIComponent('Olá! Vi o anúncio do '+car.make+' '+car.model+' na Vértice Motors e gostaria de mais informações.')}" aria-label="Falar com vendedor sobre ${escapeAttr(car.make+' '+car.model)}">${own?'Falar no WhatsApp ↗':'Tenho interesse ↗'}</a></div>${own?`<button type="button" class="delete-listing" data-remove="${escapeAttr(car.id)}">Remover anúncio</button>`:''}</div></article>`;}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const escapeAttr=escapeHTML;
function renderInventory(){const query=$('search-query').value.trim().toLocaleLowerCase('pt-BR'),make=$('filter-make').value,sort=$('sort-price').value,storefrontId=storefrontSellerId();let shown=cars.filter(car=>(!storefrontId||car.sellerId===storefrontId)&&(!make||car.make===make)&&(!query||`${car.make} ${car.model} ${car.location}`.toLocaleLowerCase('pt-BR').includes(query)));if(sort==='low')shown.sort((a,b)=>a.price-b.price);if(sort==='high')shown.sort((a,b)=>b.price-a.price);inventory.innerHTML=shown.map(c=>cardHTML(c)).join('');if(viewObserver)inventory.querySelectorAll('[data-listing-id]').forEach(card=>{if(!seenListings.has(card.dataset.listingId))viewObserver.observe(card);});const storefrontName=storefrontStore?.displayName||(storefrontId?cars.find(c=>c.sellerId===storefrontId)?.sellerName:null);$('inventory-title').textContent=storefrontName?`Carros de ${storefrontName}`:'Carros para ir mais longe.';$('inventory-copy').textContent=storefrontId?'Fale diretamente com o vendedor pelo WhatsApp em cada anúncio.':'Escolha com calma. Encontre o seu próximo caminho.';$('search-form').hidden=!!storefrontId;$('empty-stock').hidden=shown.length>0;$('stock-count').textContent=`${cars.length} ${cars.length===1?'carro disponível':'carros disponíveis'}`;const prior=make;$('filter-make').innerHTML='<option value="">Todas as marcas</option>'+[...new Set(cars.map(c=>c.make))].sort().map(m=>`<option value="${escapeAttr(m)}">${escapeHTML(m)}</option>`).join('');$('filter-make').value=prior;}
function renderSeller(){if(!seller){$('seller-panel').hidden=true;return;}$('seller-panel').hidden=false;$('admin-shortcut').hidden=!seller.isAdmin;$('seller-welcome').textContent=`Olá, ${seller.displayName}.`;$('share-store').onclick=async()=>{let slug=seller.storeSlug;if(!slug){try{slug=(await api('store')).storeSlug;seller.storeSlug=slug;}catch{}}const link=new URL(location.href);link.search='';link.hash='';if(slug)link.searchParams.set('loja',slug);else link.searchParams.set('vendedor',seller.id);link.hash='estoque';try{await navigator.clipboard.writeText(link.href);$('share-message').textContent='Link da sua loja copiado!';}catch{$('share-message').textContent=link.href;}};$('seller-listings').innerHTML=(myListings.length?myListings:cars.filter(c=>c.sellerId===seller.id)).map(c=>cardHTML(c,true)).join('')||'<p class="my-empty">Você ainda não publicou nenhum carro.</p>';document.querySelectorAll('[data-remove]').forEach(btn=>btn.addEventListener('click',()=>removeListing(btn.dataset.remove)));}
async function api(path,options={}){const multipart=options.body instanceof FormData;const response=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{...(options.body&&!multipart?{'content-type':'application/json'}:{}),...options.headers}});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'Não foi possível concluir.');return result;}
async function load(){const inventoryRequest=storeSlugParam?api('stores/'+encodeURIComponent(storeSlugParam)):api('listings');const [inventoryResult,sessionResult]=await Promise.allSettled([inventoryRequest,api('session')]);if(inventoryResult.status==='fulfilled'){storefrontStore=inventoryResult.value.store||null;cars=inventoryResult.value.listings||[];renderInventory();}else{$('empty-stock').hidden=false;$('empty-stock').querySelector('h3').textContent=storeSlugParam?'Esta loja não foi encontrada.':'Não foi possível carregar os anúncios.';$('empty-stock').querySelector('p').textContent=storeSlugParam?'Confira o link com o vendedor ou explore o estoque completo da Vértice Motors.':'Tente novamente em instantes.';}if(sessionResult.status==='fulfilled'){seller=sessionResult.value.seller;if(seller){try{myListings=(await api('listings?mine=1')).listings||[];}catch{myListings=[];}}else myListings=[];renderSeller();}else seller=null;}
function showAuth(mode='register'){authMode=mode;$('seller-name').closest('label').hidden=mode==='login';$('seller-name').required=mode==='register';$('seller-password').autocomplete=mode==='login'?'current-password':'new-password';$('auth-title').textContent=mode==='login'?'Bem-vindo de volta.':'Anuncie com a Vértice.';$('auth-copy').textContent=mode==='login'?'Entre para gerenciar seus anúncios.':'Crie sua conta de vendedor gratuita.';$('auth-submit').innerHTML=mode==='login'?'Entrar <span>↗</span>':'Criar conta <span>↗</span>';$('auth-toggle').textContent=mode==='login'?'Criar uma nova conta':'Já tenho uma conta. Entrar';$('forgot-password').hidden=mode!=='login';message('auth-message','');authDialog.showModal();}
async function removeListing(id){if(!confirm('Remover este anúncio do estoque?'))return;try{await api(`listings/${encodeURIComponent(id)}`,{method:'DELETE'});await load();}catch(error){message('auth-message',error.message,true);}}
$('seller-login').addEventListener('click',()=>showAuth(seller?'login':'register'));
$('empty-login').addEventListener('click',()=>showAuth());
$('auth-toggle').addEventListener('click',()=>showAuth(authMode==='register'?'login':'register'));
$('forgot-password').addEventListener('click',()=>{const email=$('seller-email').value.trim();$('recovery-email').value=email;message('recovery-message','');authDialog.close();recoveryDialog.showModal();});
$('recovery-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;try{await api('password-reset',{method:'POST',body:JSON.stringify({email:$('recovery-email').value})});message('recovery-message','Se este e-mail estiver cadastrado, enviaremos um link para redefinir a senha.');}catch(error){message('recovery-message',error.message,true);}finally{button.disabled=false;}});
$('reset-form').addEventListener('submit',async event=>{event.preventDefault();if($('reset-password').value!==$('reset-password-confirm').value)return message('reset-message','As senhas não coincidem.',true);const button=event.currentTarget.querySelector('button[type="submit"]');button.disabled=true;try{await api('password-reset/complete',{method:'POST',body:JSON.stringify({token:$('reset-token').value,password:$('reset-password').value})});resetDialog.close();history.replaceState(null,'',location.pathname+location.search);showAuth('login');message('auth-message','Senha alterada. Entre com sua nova senha.');}catch(error){message('reset-message',error.message,true);}finally{button.disabled=false;}});
$('auth-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('auth-submit');button.disabled=true;try{const input={email:$('seller-email').value,password:$('seller-password').value};if(authMode==='register')input.name=$('seller-name').value;const result=await api(authMode==='register'?'register':'login',{method:'POST',body:JSON.stringify(input)});seller=result.seller;authDialog.close();await load();$('seller-panel').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){message('auth-message',error.message,true);}finally{button.disabled=false;}});
$('seller-logout').addEventListener('click',async()=>{try{await api('logout',{method:'POST'});seller=null;await load();}catch(error){message('auth-message',error.message,true);}});
$('add-listing').addEventListener('click',()=>{if(!seller)return showAuth();$('listing-form').reset();message('listing-message','');listingDialog.showModal();});
$('listing-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const raw=Object.fromEntries(new FormData(form));const body={...raw,image:null,year:Number(raw.year),mileage:Number(raw.mileage),price:Math.round(Number(raw.price.replace(/\./g,'').replace(',','.'))*100)};try{const photo=photoField.files?.[0];if(photo){const data=new FormData();data.append('file',photo);body.image=(await api('images',{method:'POST',body:data})).key;}await api('listings',{method:'POST',body:JSON.stringify(body)});listingDialog.close();await load();$('seller-panel').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){message('listing-message',error.message,true);}});
$('search-query').addEventListener('input',renderInventory);$('filter-make').addEventListener('change',renderInventory);$('sort-price').addEventListener('change',renderInventory);$('search-form').addEventListener('submit',event=>{event.preventDefault();renderInventory();});
load().then(()=>{if(storefrontSellerId()||storeSlugParam){$('hero-title').innerHTML='A loja de carros<br><em>que você procura.</em>';document.querySelector('.edition strong').innerHTML='Ver estoque <i>↘</i>';}if(resetToken){$('reset-token').value=resetToken;resetDialog.showModal();}});
